package it.unimi.dsi.fastutil.longs; public class Long2LongOpenHashMap implements Long2LongMap { final java.util.HashMap<Long,Long> m=new java.util.HashMap<>(); long def;
 public void defaultReturnValue(long v){def=v;} public long get(long k){Long v=m.get(k); return v==null?def:v;} public long put(long k,long v){Long o=m.put(k,v); return o==null?def:o;}
 public it.unimi.dsi.fastutil.objects.ObjectSet<Long2LongMap.Entry> long2LongEntrySet(){ return new it.unimi.dsi.fastutil.objects.ObjectSetImpl<Long2LongMap.Entry>(){ public boolean removeIf(java.util.function.Predicate<? super Long2LongMap.Entry> p){ return m.entrySet().removeIf(e -> p.test(new Long2LongMap.Entry(){ public Long getKey(){return e.getKey();} public Long getValue(){return e.getValue();} public long getLongValue(){return e.getValue();} public Long setValue(Long x){throw new UnsupportedOperationException();} })); } }; } }
